import React from 'react';
import './Skills.css';

const Skills = () => {
  const skillCategories = [
    {
      category: "Programming Languages",
      skills: [
        { name: "JavaScript", level: 95 },
        { name: "Python", level: 90 },
        { name: "TypeScript", level: 85 },
        { name: "Java", level: 80 },
        { name: "C++", level: 75 },
        { name: "Go", level: 70 }
      ]
    },
    {
      category: "Frontend Technologies",
      skills: [
        { name: "React", level: 95 },
        { name: "Vue.js", level: 80 },
        { name: "HTML5/CSS3", level: 90 },
        { name: "Angular", level: 75 },
        { name: "Svelte", level: 65 },
        { name: "React Native", level: 70 }
      ]
    },
    {
      category: "Backend & Database",
      skills: [
        { name: "Node.js", level: 90 },
        { name: "Express.js", level: 85 },
        { name: "MongoDB", level: 85 },
        { name: "PostgreSQL", level: 80 },
        { name: "Redis", level: 75 },
        { name: "GraphQL", level: 70 }
      ]
    },
    {
      category: "Cloud & DevOps",
      skills: [
        { name: "AWS", level: 85 },
        { name: "Docker", level: 80 },
        { name: "Kubernetes", level: 75 },
        { name: "Google Cloud", level: 70 },
        { name: "Azure", level: 65 },
        { name: "Terraform", level: 60 }
      ]
    },
    {
      category: "Machine Learning & AI",
      skills: [
        { name: "TensorFlow", level: 80 },
        { name: "PyTorch", level: 75 },
        { name: "Scikit-learn", level: 85 },
        { name: "Pandas", level: 90 },
        { name: "NumPy", level: 85 },
        { name: "OpenCV", level: 70 }
      ]
    },
    {
      category: "Tools & Other",
      skills: [
        { name: "Git", level: 95 },
        { name: "Linux", level: 85 },
        { name: "Webpack", level: 80 },
        { name: "Jest", level: 85 },
        { name: "Figma", level: 70 },
        { name: "Jira", level: 75 }
      ]
    }
  ];

  const getSkillColor = (level) => {
    if (level >= 90) return '#10b981'; // Green
    if (level >= 80) return '#3b82f6'; // Blue
    if (level >= 70) return '#f59e0b'; // Yellow
    return '#ef4444'; // Red
  };

  return (
    <section id="skills" className="section">
      <div className="container">
        <h2 className="section-title">Skills & Technologies</h2>
        <div className="skills-grid">
          {skillCategories.map((category, index) => (
            <div key={index} className="skill-category card">
              <h3 className="category-title">{category.category}</h3>
              <div className="skills-list">
                {category.skills.map((skill, skillIndex) => (
                  <div key={skillIndex} className="skill-item">
                    <div className="skill-header">
                      <span className="skill-name">{skill.name}</span>
                      <span className="skill-percentage">{skill.level}%</span>
                    </div>
                    <div className="skill-bar">
                      <div 
                        className="skill-progress"
                        style={{ 
                          width: `${skill.level}%`,
                          backgroundColor: getSkillColor(skill.level)
                        }}
                      ></div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div className="skills-summary">
          <div className="summary-content">
            <h3>Technical Expertise</h3>
            <p>
              With over 5 years of experience in software development, I have developed expertise 
              across the full technology stack. My strongest areas include frontend development 
              with React, backend systems with Node.js, and cloud infrastructure on AWS. I'm 
              passionate about machine learning and have applied AI techniques to solve real-world 
              problems in various domains.
            </p>
            <div className="expertise-highlights">
              <div className="highlight">
                <span className="highlight-icon">🚀</span>
                <div>
                  <h4>Full-Stack Development</h4>
                  <p>End-to-end web application development</p>
                </div>
              </div>
              <div className="highlight">
                <span className="highlight-icon">☁️</span>
                <div>
                  <h4>Cloud Architecture</h4>
                  <p>Scalable and resilient cloud solutions</p>
                </div>
              </div>
              <div className="highlight">
                <span className="highlight-icon">🤖</span>
                <div>
                  <h4>Machine Learning</h4>
                  <p>AI/ML model development and deployment</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Skills;
